// testbench.v
// Self-checking testbench for the 5-stage pipelined RV32I cpu_pipe.
// Runs program.hex (generated by program.py / golden_sim.py) and compares
// the final register file contents against a golden (non-pipelined)
// functional simulation of the same program.
`timescale 1ns/1ps

module testbench;
    reg clk, rst;
    integer i, errors;
    reg [31:0] expected [0:31];

    cpu_pipe uut (.clk(clk), .rst(rst));

    // 10ns clock period
    initial clk = 0;
    always #5 clk = ~clk;

    initial begin
        expected[0] = 32'h00000000;
        expected[1] = 32'hffffffff;
        expected[2] = 32'h00000001;
        expected[3] = 32'h0000000f;
        expected[4] = 32'h0000000f;
        expected[5] = 32'h00000064;
        expected[6] = 32'h00000064;
        expected[7] = 32'h00000065;
        expected[8] = 32'h00000055;
        expected[9] = 32'h00000055;
        expected[10] = 32'h00000000;
        expected[11] = 32'h0000006f;
        expected[12] = 32'h0000014d;
        expected[13] = 32'hffffffff;
        expected[14] = 32'h0000029a;
        expected[15] = 32'h0000000f;
        expected[16] = 32'h00000378;
        expected[17] = 32'h000003e7;
        expected[18] = 32'h00000005;
        expected[19] = 32'hfffffffc;
        expected[20] = 32'h000000e0;
        expected[21] = 32'h00000001;
        expected[22] = 32'h000007d0;
        expected[23] = 32'h000000f4;
        expected[24] = 32'h000000f0;
        expected[25] = 32'h00000000;
        expected[26] = 32'habcde000;
        expected[27] = 32'h000010f8;
        expected[28] = 32'h00000000;
        expected[29] = 32'h00000003;
        expected[30] = 32'h000007ff;
        expected[31] = 32'h000007ff;

        rst = 1;
        repeat (3) @(posedge clk);
        rst = 0;

        // Run long enough for: 71 instrs + pipeline fill/drain + stalls/flushes
        // from load-use hazards and taken branches/jumps. 400 cycles is generous.
        repeat (400) @(posedge clk);

        errors = 0;
        $display("================ Register file check ================");
        // x0's underlying storage is never written (only forced to 0 through the
        // regfile's read mux), and this design never resets the x[] array itself -
        // so any architectural register that the program never writes will also
        // read back X here. That's a real design property worth knowing (no
        // power-on/reset init of the register file), not a pipeline bug, so we
        // start the loop at x1 and treat X only as suspicious if the golden model
        // expected a non-zero/written value.
        for (i = 1; i < 32; i = i + 1) begin
            if (uut.rfile.x[i] !== expected[i]) begin
                $display("FAIL x%0d: got 0x%08h expected 0x%08h", i, uut.rfile.x[i], expected[i]);
                errors = errors + 1;
            end else begin
                $display("PASS x%0d = 0x%08h", i, uut.rfile.x[i]);
            end
        end
        $display("=======================================================");
        if (errors == 0)
            $display("ALL CHECKS PASSED");
        else
            $display("%0d CHECK(S) FAILED", errors);

        $finish;
    end

    // safety timeout
    initial begin
        #10000;
        $display("TIMEOUT - simulation did not finish");
        $finish;
    end

    // optional waveform dump
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0, testbench);
    end
endmodule
